'use strict';
let rigMaskPending=null;
let rigMaskCanvas=null,rigMaskOriginal=null,rigMaskDrag=null,rigMaskUndo=[],personSegmenter=null,rigMaskBusy=false;
document.querySelector('.rig-paper').before(Object.assign(document.createElement('details'),{id:'rigCutoutTools',innerHTML:`<summary>Background removal & cut-out brush</summary><div class="rig-tools"><select id="rigMaskTarget" aria-label="Mask target"><option value="source">Character picture</option><option value="part">Selected body part</option></select><button id="rigRemovePersonBackground">Remove person background</button><button id="rigRemoveEdgeBackground">Remove edge color</button><label>Tolerance<input id="rigMaskTolerance" type="range" min="10" max="110" value="40"></label><button id="rigEraseMask">Erase brush</button><button id="rigRestoreMask">Restore brush</button><label>Brush<input id="rigMaskSize" type="range" min="2" max="120" value="28"></label><button id="rigUndoMask">Undo mask</button><button id="rigResetMask">Restore original</button></div><p class="note">Person removal runs on this PC. Clean hair, complex backgrounds and overlapping limbs with the erase/restore brush. Edge color removal works best on plain backgrounds. Cut parts after cleaning the picture.</p></details>`}));
function maskTarget(){if(!imageRigDraft)return null;return $('rigMaskTarget').value==='part'?currentRigPart():imageRigDraft}
function maskSrcKey(target){return target===imageRigDraft?'imageSrc':'src'}
async function prepareRigMask(){const target=maskTarget();if(!target)return toast('Select a body part first.');const key=maskSrcKey(target),src=target[key];if(!src)return toast('Import a character picture first.');const originalKey=target===imageRigDraft?'originalImageSrc':'originalSrc';target[originalKey]??=src;const image=await imageReady(src),original=await imageReady(target[originalKey]);rigMaskCanvas=document.createElement('canvas');rigMaskCanvas.width=target===imageRigDraft?target.imageWidth:Math.round(target.width);rigMaskCanvas.height=target===imageRigDraft?target.imageHeight:Math.round(target.height);rigMaskCanvas.getContext('2d').drawImage(image,0,0,rigMaskCanvas.width,rigMaskCanvas.height);rigMaskOriginal=document.createElement('canvas');rigMaskOriginal.width=rigMaskCanvas.width;rigMaskOriginal.height=rigMaskCanvas.height;rigMaskOriginal.getContext('2d').drawImage(original,0,0,rigMaskOriginal.width,rigMaskOriginal.height);return{target,key,canvas:rigMaskCanvas,original:rigMaskOriginal,x:target===imageRigDraft?0:target.x,y:target===imageRigDraft?0:target.y}}
function rememberRigMask(info){rigMaskUndo.push({target:info.target,key:info.key,src:info.target[info.key]});if(rigMaskUndo.length>12)rigMaskUndo.shift()}
async function commitRigMask(info){info.target[info.key]=info.canvas.toDataURL('image/png');await imageReady(info.target[info.key]);paintRigEditor()}
async function getPersonSegmenter(){if(!personSegmenter){const {FilesetResolver,ImageSegmenter}=await import('./vendor/mediapipe/vision_bundle.js');const files=await FilesetResolver.forVisionTasks(new URL('./vendor/mediapipe/wasm',location.href).href);personSegmenter=await ImageSegmenter.createFromOptions(files,{baseOptions:{modelAssetPath:new URL('./vendor/mediapipe/selfie_segmenter.tflite',location.href).href,delegate:'CPU'},runningMode:'IMAGE',outputCategoryMask:false,outputConfidenceMasks:true})}return personSegmenter}
async function removePersonBackground(){if(rigMaskBusy)return;rigMaskBusy=true;for(const id of ['rigRemovePersonBackground','rigRemoveEdgeBackground','rigEraseMask','rigRestoreMask','rigUndoMask','rigResetMask','rigSourceFile','rigPartFiles','saveImageRig','closeImageRig'])$(id).disabled=true;$('rigHint').textContent='Finding the person locally…';try{const info=await prepareRigMask();if(!info)return;const segmenter=await getPersonSegmenter();rememberRigMask(info);const c=info.canvas.getContext('2d'),pixels=c.getImageData(0,0,info.canvas.width,info.canvas.height);segmenter.segment(info.canvas,result=>{const masks=result.confidenceMasks,mask=masks.length>1?masks[1]:masks[0],values=mask.getAsFloat32Array(),w=mask.width,h=mask.height;for(let y=0;y<info.canvas.height;y++)for(let x=0;x<info.canvas.width;x++){const confidence=values[Math.min(h-1,Math.floor(y*h/info.canvas.height))*w+Math.min(w-1,Math.floor(x*w/info.canvas.width))],alpha=clamp((confidence-.2)/.6,0,1);pixels.data[(y*info.canvas.width+x)*4+3]*=alpha}});c.putImageData(pixels,0,0);await commitRigMask(info);$('rigHint').textContent='Background removed. Use erase/restore brushes to refine the edges.'}catch(error){toast('Person removal could not run. Use edge removal or the brush. '+error.message)}finally{rigMaskBusy=false;for(const id of ['rigRemovePersonBackground','rigRemoveEdgeBackground','rigEraseMask','rigRestoreMask','rigUndoMask','rigResetMask','rigSourceFile','rigPartFiles','saveImageRig','closeImageRig'])$(id).disabled=false}}
function edgeMaskPixels(pixels,w,h,tolerance){const data=pixels.data,bins=new Map(),add=i=>{if(data[i+3]<32)return;const key=[data[i]>>5,data[i+1]>>5,data[i+2]>>5].join(',');let bin=bins.get(key);if(!bin){bin={n:0,r:0,g:0,b:0};bins.set(key,bin)}bin.n++;bin.r+=data[i];bin.g+=data[i+1];bin.b+=data[i+2]};for(let x=0;x<w;x++){add(x*4);add(((h-1)*w+x)*4)}for(let y=1;y<h-1;y++){add(y*w*4);add((y*w+w-1)*4)}const colors=[...bins.values()].sort((a,b)=>b.n-a.n).slice(0,3).map(c=>[c.r/c.n,c.g/c.n,c.b/c.n]),seen=new Uint8Array(w*h),queue=new Int32Array(w*h);let head=0,tail=0;const visit=i=>{if(seen[i])return;seen[i]=1;const at=i*4;if(data[at+3]>0&&!colors.some(c=>Math.hypot(data[at]-c[0],data[at+1]-c[1],data[at+2]-c[2])<=tolerance))return;queue[tail++]=i;data[at+3]=0};for(let x=0;x<w;x++){visit(x);visit((h-1)*w+x)}for(let y=1;y<h-1;y++){visit(y*w);visit(y*w+w-1)}while(head<tail){const i=queue[head++],x=i%w,y=Math.floor(i/w);if(x)visit(i-1);if(x<w-1)visit(i+1);if(y)visit(i-w);if(y<h-1)visit(i+w)}return tail}
$('rigRemovePersonBackground').onclick=removePersonBackground;$('rigRemoveEdgeBackground').onclick=async()=>{const info=await prepareRigMask();if(!info)return;rememberRigMask(info);const c=info.canvas.getContext('2d'),pixels=c.getImageData(0,0,info.canvas.width,info.canvas.height);edgeMaskPixels(pixels,info.canvas.width,info.canvas.height,+$('rigMaskTolerance').value);c.putImageData(pixels,0,0);await commitRigMask(info);$('rigHint').textContent='Edge background removed. Brush back any details you want to keep.'};
for(const[id,mode]of[['rigEraseMask','mask-erase'],['rigRestoreMask','mask-restore']])$(id).onclick=async()=>{if(await prepareRigMask()){rigMode=mode;rigPolygon=[];$('rigHint').textContent=mode==='mask-erase'?'Brush over unwanted pixels.':'Brush to restore pixels from the original picture.';paintRigEditor()}};
$('rigUndoMask').onclick=async()=>{const last=rigMaskUndo.pop();if(!last)return;last.target[last.key]=last.src;await imageReady(last.src);paintRigEditor()};$('rigResetMask').onclick=async()=>{const info=await prepareRigMask();if(!info)return;rememberRigMask(info);info.target[info.key]=info.target[info.target===imageRigDraft?'originalImageSrc':'originalSrc'];await imageReady(info.target[info.key]);paintRigEditor()};
function strokeRigMask(info,from,to){const c=info.canvas.getContext('2d'),radius=+$("rigMaskSize").value/2,a={x:from.x-info.x,y:from.y-info.y},b={x:to.x-info.x,y:to.y-info.y},left=Math.max(0,Math.floor(Math.min(a.x,b.x)-radius)),top=Math.max(0,Math.floor(Math.min(a.y,b.y)-radius)),right=Math.min(info.canvas.width,Math.ceil(Math.max(a.x,b.x)+radius)),bottom=Math.min(info.canvas.height,Math.ceil(Math.max(a.y,b.y)+radius));if(right<=left||bottom<=top)return;const w=right-left,h=bottom-top,pixels=c.getImageData(left,top,w,h),original=info.original.getContext('2d').getImageData(left,top,w,h),dx=b.x-a.x,dy=b.y-a.y,den=dx*dx+dy*dy;for(let y=0;y<h;y++)for(let x=0;x<w;x++){const px=left+x+.5,py=top+y+.5,f=den?clamp(((px-a.x)*dx+(py-a.y)*dy)/den,0,1):0;if(Math.hypot(px-a.x-dx*f,py-a.y-dy*f)>radius)continue;const i=(y*w+x)*4;if(rigMode==='mask-restore')for(let k=0;k<4;k++)pixels.data[i+k]=original.data[i+k];else pixels.data[i+3]=0}c.putImageData(pixels,left,top)}

const paintBeforeMask=paintRigEditor;paintRigEditor=function(){paintBeforeMask();if(rigMaskDrag){const d=rigMaskDrag;rigContext.clearRect(0,0,rigCanvas.width,rigCanvas.height);rigContext.drawImage(d.info.canvas,d.info.x,d.info.y);rigContext.strokeStyle='#fff';rigContext.lineWidth=1.5;rigContext.beginPath();rigContext.arc(d.last.x,d.last.y,+$('rigMaskSize').value/2,0,Math.PI*2);rigContext.stroke()}};
const rigDownBeforeMask=rigCanvas.onpointerdown,rigMoveBeforeMask=rigCanvas.onpointermove,rigUpBeforeMask=rigCanvas.onpointerup,rigCancelBeforeMask=rigCanvas.onpointercancel;
rigCanvas.onpointerdown=async e=>{if(!rigMode.startsWith('mask-'))return rigDownBeforeMask(e);if(e.button||rigMaskBusy)return;const p=rigPoint(e),pending={from:p,last:p,ended:false};rigMaskPending=pending;rigCanvas.setPointerCapture(e.pointerId);const info=await prepareRigMask();if(!info||rigMaskPending!==pending)return;rememberRigMask(info);rigMaskDrag={info,last:pending.last};strokeRigMask(info,pending.from,pending.last);rigMaskPending=null;if(pending.ended){rigMaskDrag=null;await commitRigMask(info)}else paintRigEditor()};
rigCanvas.onpointermove=e=>{if(rigMaskPending){rigMaskPending.last=rigPoint(e);return}if(!rigMaskDrag)return rigMoveBeforeMask(e);const p=rigPoint(e);strokeRigMask(rigMaskDrag.info,rigMaskDrag.last,p);rigMaskDrag.last=p;paintRigEditor()};rigCanvas.onpointerup=async()=>{if(rigMaskPending){rigMaskPending.ended=true;return}if(!rigMaskDrag)return rigUpBeforeMask();const info=rigMaskDrag.info;rigMaskDrag=null;await commitRigMask(info)};rigCanvas.onpointercancel=()=>{if(rigMaskPending){rigMaskPending=null;return}if(rigMaskDrag){rigMaskDrag=null;$("rigUndoMask").click()}else rigCancelBeforeMask()};

const openBeforeMask=openImageRig;openImageRig=function(...args){rigMaskUndo=[];rigMaskDrag=null;return openBeforeMask(...args)};

const sourceBeforeMask=$("rigSourceFile").onchange;$("rigSourceFile").onchange=async e=>{if(rigMaskBusy||rigMaskPending||rigMaskDrag)return;rigMaskUndo=[];return sourceBeforeMask(e)};$("imageRigDialog").addEventListener('cancel',e=>{if(rigMaskBusy||rigMaskPending||rigMaskDrag)e.preventDefault()});
